import zlib, base64
from pathlib import Path

payload = ""
target = Path("macos-app/Sources/NotepadPlusMac/Editor/MacEditorView.swift")
if not target.parent.exists():
    target = Path("Sources/NotepadPlusMac/Editor/MacEditorView.swift")

target.write_bytes(zlib.decompress(base64.b64decode(payload)))
print(f"Successfully updated {target} ({target.stat().st_size} bytes)")
